package io.github.miclean.tests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.util.concurrent.atomic.*;
public final class SkipRepeatExternalSmoke extends Instrumentation {
    private final AtomicInteger notices=new AtomicInteger();private int checks;private volatile Activity current;private String mode;
    @Override public void onCreate(Bundle b){super.onCreate(b);mode=b==null?"node":b.getString("mode","node");start();}
    @Override public void callActivityOnResume(Activity a){super.callActivityOnResume(a);current=a;}
    private void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
    private boolean has(View v,String s){if(v instanceof TextView&&s.contentEquals(((TextView)v).getText()))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(has(((ViewGroup)v).getChildAt(i),s))return true;return false;}
    private boolean notice(UiAutomation ua){android.util.SparseArray<java.util.List<AccessibilityWindowInfo>> displays=ua.getWindowsOnAllDisplays();for(int i=0;i<displays.size();i++)for(AccessibilityWindowInfo w:displays.valueAt(i)){if(displays.keyAt(i)!=0)continue;AccessibilityNodeInfo r=w.getRoot();if(r!=null){boolean found="io.github.miclean.module".contentEquals(r.getPackageName())&&noticeNode(r);r.recycle();if(found)return true;}}return false;}
    private boolean noticeNode(AccessibilityNodeInfo n){if("跳过操作验证🙂".equals(n.getText()==null?null:n.getText().toString()))return true;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null){boolean found=noticeNode(c);c.recycle();if(found)return true;}}return false;}
    @Override public void onStart(){Bundle out=new Bundle();try{UiAutomation ua=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);android.accessibilityservice.AccessibilityServiceInfo info=ua.getServiceInfo();info.eventTypes=AccessibilityEvent.TYPES_ALL_MASK;info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;ua.setServiceInfo(info);ua.setOnAccessibilityEventListener(e->{if(e.getEventType()==AccessibilityEvent.TYPE_NOTIFICATION_STATE_CHANGED&&e.getText().toString().contains("跳过操作验证🙂"))notices.incrementAndGet();});
        for(int round=0;round<5;round++){
            if(round==0){for(int i=0;i<100&&current==null;i++)SystemClock.sleep(100);check(current!=null,"External fixture launch required");}
            else {SystemClock.sleep(2200);Activity old=current;runOnMainSync(()->{Intent launch=new Intent().setClassName(getTargetContext().getPackageName(),"io.github.miclean.skipfixture.FixtureActivity").putExtra("mode",mode.equals("chain")?"chain":"repeat").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK);ActivityOptions options=ActivityOptions.makeBasic();options.setLaunchDisplayId(0);old.startActivity(launch,options.toBundle());});for(int i=0;i<100&&current==old;i++)SystemClock.sleep(50);check(current!=old,"Fixture did not reopen on default display");}
            Activity a=current;boolean[] clicked={false};
            for(int i=0;i<100;i++){runOnMainSync(()->clicked[0]=current!=null&&has(current.getWindow().getDecorView(),"测试广告已关闭"));if(clicked[0])break;SystemClock.sleep(80);}check(clicked[0],"Same named Activity did not execute on round "+(round+1));
            if(mode.equals("center")){int device=current.getClass().getField("lastInputDeviceId").getInt(current);check(device!=Integer.MIN_VALUE,"No touch input reached the actual fixture");Bundle input=new Bundle();input.putString("stream","Actual touch delivered; device="+device+"\n");sendStatus(0,input);}
            if(mode.equals("chain")){long elapsed=current.getClass().getField("chainElapsedMs").getLong(current);check(elapsed>=0&&elapsed<300,"Second rule waited for poll / stale tree: "+elapsed+"ms");Bundle timing=new Bundle();timing.putString("stream","Sequential fresh-root action gap: "+elapsed+"ms\n");sendStatus(0,timing);}
            SystemClock.sleep(350);android.graphics.Bitmap shot=ua.takeScreenshot();check(shot!=null,"No feedback screenshot");try(java.io.FileOutputStream stream=new java.io.FileOutputStream(new java.io.File(getTargetContext().getCacheDir(),"skip-feedback-"+round+".png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream);}finally{shot.recycle();}
            Bundle progress=new Bundle();progress.putString("stream","Round "+(round+1)+" real action completed in same package/Activity.\n");sendStatus(0,progress);
        }
        out.putString("stream","PASS: "+checks+" real-service checks; same Activity reopened 5 times beyond matchTime with actionMaximum=1, 5 feedback screenshots saved for pixel inspection.\n");
    }catch(Throwable e){try{android.graphics.Bitmap shot=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).takeScreenshot();if(shot!=null){try(java.io.FileOutputStream stream=new java.io.FileOutputStream(new java.io.File(getTargetContext().getCacheDir(),"skip-failure.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream);}shot.recycle();}}catch(Throwable ignored){}out.putString("stream","FAIL: "+e+"\n");}finish(out.getString("stream","").startsWith("PASS:")?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
